using Marina.Domain.Common;
namespace Marina.Domain.Security;
public sealed class Permission : Entity { public string Name { get; set; }=""; public string Description { get; set; }=""; }
public sealed class RolePermission : Entity { public Guid RoleId { get; set; } public Guid PermissionId { get; set; } }
public sealed class UserSession : Entity { public Guid UserId { get; set; } public Guid FamilyId { get; set; }=Guid.NewGuid(); public string DeviceName { get; set; }=""; public string UserAgent { get; set; }=""; public string IpAddress { get; set; }=""; public DateTime LastSeenUtc { get; set; }=DateTime.UtcNow; public DateTime? RevokedUtc { get; set; } public ICollection<RefreshToken> RefreshTokens { get; set; }=[]; }
public sealed class RefreshToken : Entity { public Guid UserSessionId { get; set; } public UserSession UserSession { get; set; }=null!; public string TokenHash { get; set; }=""; public DateTime ExpiresUtc { get; set; } public DateTime? RevokedUtc { get; set; } public Guid? ReplacedById { get; set; } public bool IsReuseDetected { get; set; } }
public sealed class LoginAttempt : Entity { public Guid? UserId { get; set; } public string NormalizedIdentifierHash { get; set; }=""; public string IpAddress { get; set; }=""; public bool Succeeded { get; set; } public string? FailureReason { get; set; } }
public sealed class SecurityEvent : Entity { public Guid? UserId { get; set; } public string EventType { get; set; }=""; public string Severity { get; set; }="Information"; public string IpAddress { get; set; }=""; public string UserAgent { get; set; }=""; public string CorrelationId { get; set; }=""; public string Details { get; set; }=""; }
public sealed class AuditLog : Entity { public Guid? UserId { get; set; } public string Action { get; set; }=""; public string EntityName { get; set; }=""; public string EntityId { get; set; }=""; public string IpAddress { get; set; }=""; public string CorrelationId { get; set; }=""; public string? OldValuesJson { get; set; } public string? NewValuesJson { get; set; } }
public sealed class AppSetting : Entity { public string Key { get; set; }=""; public string Value { get; set; }=""; public bool IsPublic { get; set; } }
